1	export const stripUrl = (msg: string): string => {
2	    if (!msg) return '';
3	
4	    try {
5	        // Basic regex to find a URL in the text
6	        const urlMatch = msg.match(/(https?:\/\/[^\s]+)/);
7	        const urlString = urlMatch ? urlMatch[0] : msg.trim();
8	
9	        const url = new URL(urlString);
10	
11	        // Only strip parameters if it's a TikTok domain
12	        if (url.hostname.includes('tiktok.com')) {
13	            url.search = '';
14	        }
15	
16	        return url.toString();
17	    } catch (e) {
18	        // If invalid URL, return original input to avoid confusing the user
19	        return msg;
20	    }
21	};
