3	export async function GET(request: NextRequest) {
4	    const { searchParams } = new URL(request.url);
5	    const url = searchParams.get('url');
6	
7	    if (!url) {
8	        return NextResponse.json({ error: 'Missing URL parameter' }, { status: 400 });
9	    }
10	
11	    try {
12	        // We use 'follow' to let fetch chase the redirects (usually 301/302 from TikTok)
13	        // HEAD request is faster as we only need the final URL, not the body
14	        const response = await fetch(url, {
15	            method: 'HEAD',
16	            redirect: 'follow',
17	            headers: {
18	                'User-Agent': 'Mozilla/5.0 (compatible; Googlebot/2.1; +http://www.google.com/bot.html)',
19	            },
20	        });
21	
22	        return NextResponse.json({ url: response.url });
23	    } catch (error) {
24	        console.error('Expansion error:', error);
25	        return NextResponse.json({ error: 'Failed to expand URL' }, { status: 500 });
26	    }
27	}
