"use client";

import React, { useState } from "react";
import { useStrippedLink } from "@/features/link-stripper";
import { LinkInput } from "@/features/link-stripper/components/LinkInput";
import { ResultDisplay } from "@/features/link-stripper/components/ResultDisplay";
import styles from "./page.module.css";

export default function Home() {
  const { isLoading, error, processLink } = useStrippedLink();
  const [result, setResult] = useState<string>("");

  const handleProcess = async (input: string) => {
    const cleanUrl = await processLink(input);
    setResult(cleanUrl);
  };

  return (
    <main className={styles.page}>
      <div className={styles.header}>
        <h1 className={styles.title}>TikTok Link Stripper</h1>
        <p className={styles.subtitle}>Remove tracking parameters. Share clean links.</p>
      </div>

      <LinkInput onProcess={handleProcess} isLoading={isLoading} error={error} />

      {result && <ResultDisplay url={result} />}
    </main>
  );
}
