119	// app/hooks/useTheme.ts
120	"use client";
121	
122	import { useState, useEffect, useCallback } from "react";
123	
124	type Theme = "night" | "day";
125	
126	interface UseThemeResult {
127	  theme: Theme;
128	  toggle: () => void;
129	}
130	
131	export function useTheme(): UseThemeResult {
132	  const [theme, setTheme] = useState<Theme>("night");
133	
134	  useEffect(() => {
135	    const stored = localStorage.getItem("theme") as Theme | null;
136	    const initial: Theme = stored === "day" ? "day" : "night";
137	    setTheme(initial);
138	    document.documentElement.setAttribute("data-theme", initial);
139	  }, []);
140	
141	  const toggle = useCallback(() => {
142	    setTheme((prev) => {
143	      const next: Theme = prev === "night" ? "day" : "night";
144	      localStorage.setItem("theme", next);
145	      document.documentElement.setAttribute("data-theme", next);
146	      return next;
147	    });
148	  }, []);
149	
150	  return { theme, toggle };
151	}
152	```
