     1→// Lightweight in-memory queue for human-readable system events that should be
     2→// prefixed to the next prompt. We intentionally avoid persistence to keep
     3→// events ephemeral. Events are session-scoped and require an explicit key.
     4→
     5→export type SystemEvent = { text: string; ts: number };
     6→
     7→const MAX_EVENTS = 20;
     8→
     9→type SessionQueue = {
    10→  queue: SystemEvent[];
    11→  lastText: string | null;
    12→  lastContextKey: string | null;
    13→};
    14→
    15→const queues = new Map<string, SessionQueue>();
    16→
    17→type SystemEventOptions = {
    18→  sessionKey: string;
    19→  contextKey?: string | null;
    20→};
    21→
    22→function requireSessionKey(key?: string | null): string {
    23→  const trimmed = typeof key === "string" ? key.trim() : "";
    24→  if (!trimmed) {
    25→    throw new Error("system events require a sessionKey");
    26→  }
    27→  return trimmed;
    28→}
    29→
    30→function normalizeContextKey(key?: string | null): string | null {
    31→  if (!key) {
    32→    return null;
    33→  }
    34→  const trimmed = key.trim();
    35→  if (!trimmed) {
    36→    return null;
    37→  }
    38→  return trimmed.toLowerCase();
    39→}
    40→
    41→export function isSystemEventContextChanged(
    42→  sessionKey: string,
    43→  contextKey?: string | null,
    44→): boolean {
    45→  const key = requireSessionKey(sessionKey);
    46→  const existing = queues.get(key);
    47→  const normalized = normalizeContextKey(contextKey);
    48→  return normalized !== (existing?.lastContextKey ?? null);
    49→}
    50→
    51→export function enqueueSystemEvent(text: string, options: SystemEventOptions) {
    52→  const key = requireSessionKey(options?.sessionKey);
    53→  const entry =
    54→    queues.get(key) ??
    55→    (() => {
    56→      const created: SessionQueue = {
    57→        queue: [],
    58→        lastText: null,
    59→        lastContextKey: null,
    60→      };
    61→      queues.set(key, created);
    62→      return created;
    63→    })();
    64→  const cleaned = text.trim();
    65→  if (!cleaned) {
    66→    return;
    67→  }
    68→  entry.lastContextKey = normalizeContextKey(options?.contextKey);
    69→  if (entry.lastText === cleaned) {
    70→    return;
    71→  } // skip consecutive duplicates
    72→  entry.lastText = cleaned;
    73→  entry.queue.push({ text: cleaned, ts: Date.now() });
    74→  if (entry.queue.length > MAX_EVENTS) {
    75→    entry.queue.shift();
    76→  }
    77→}
    78→
    79→export function drainSystemEventEntries(sessionKey: string): SystemEvent[] {
    80→  const key = requireSessionKey(sessionKey);
    81→  const entry = queues.get(key);
    82→  if (!entry || entry.queue.length === 0) {
    83→    return [];
    84→  }
    85→  const out = entry.queue.slice();
    86→  entry.queue.length = 0;
    87→  entry.lastText = null;
    88→  entry.lastContextKey = null;
    89→  queues.delete(key);
    90→  return out;
    91→}
    92→
    93→export function drainSystemEvents(sessionKey: string): string[] {
    94→  return drainSystemEventEntries(sessionKey).map((event) => event.text);
    95→}
    96→
    97→export function peekSystemEvents(sessionKey: string): string[] {
    98→  const key = requireSessionKey(sessionKey);
    99→  return queues.get(key)?.queue.map((e) => e.text) ?? [];
   100→}
   101→
   102→export function hasSystemEvents(sessionKey: string) {
   103→  const key = requireSessionKey(sessionKey);
   104→  return (queues.get(key)?.queue.length ?? 0) > 0;
   105→}
   106→
   107→export function resetSystemEventsForTest() {
   108→  queues.clear();
   109→}
