3	import { z } from "zod";
4	import { ClickUpClient } from "./clickup-api.js";
5	import { formatTask, formatComments, formatTaskList } from "./formatters.js";
6	
7	const server = new McpServer({
8	  name: "clickup",
9	  version: "1.0.0",
10	});
11	
12	const client = new ClickUpClient();
13	const TEAM_ID = "36654621";
14	
15	server.registerTool("get_task", {
16	  description: "Get full details of a ClickUp task by its custom ID (e.g. 'MP-42'). Returns description, status, assignees, custom fields, and subtasks.",
17	  inputSchema: {
18	    custom_id: z.string().describe("The custom task ID (e.g. 'MP-42')"),
19	  },
20	  annotations: { readOnlyHint: true },
21	}, async ({ custom_id }) => {
22	  const data = await client.getTask(custom_id, TEAM_ID);
23	  return { content: [{ type: "text", text: formatTask(data) }] };
24	});
25	
26	server.registerTool("get_task_comments", {
27	  description: "Get all comments on a ClickUp task by its custom ID.",
28	  inputSchema: {
29	    custom_id: z.string().describe("The custom task ID (e.g. 'MP-42')"),
30	  },
31	  annotations: { readOnlyHint: true },
32	}, async ({ custom_id }) => {
33	  const data = await client.getTaskComments(custom_id, TEAM_ID);
34	  return { content: [{ type: "text", text: formatComments(data) }] };
35	});
36	
37	server.registerTool("get_tasks", {
38	  description: "Get all tasks from a ClickUp list with optional date filtering. Auto-paginates. Returns task list with time tracking data.",
39	  inputSchema: {
40	    list_id: z.string().describe("The ClickUp list ID"),
41	    date_created_gt: z.string().optional().describe("Only tasks created after this ISO date (e.g. '2026-01-01')"),
42	    date_created_lt: z.string().optional().describe("Only tasks created before this ISO date (e.g. '2026-12-31')"),
43	    include_closed: z.boolean().optional().describe("Include closed tasks (default: true)"),
44	  },
45	  annotations: { readOnlyHint: true },
46	}, async ({ list_id, date_created_gt, date_created_lt, include_closed }) => {
47	  const tasks = await client.getTasksByList(list_id, {
48	    date_created_gt,
49	    date_created_lt,
50	    include_closed: include_closed ?? true,
51	  });
52	  return {
53	    content: [
54	      { type: "text", text: formatTaskList(tasks) },
55	      { type: "text", text: "\n\n---\nRAW_JSON_START\n" + JSON.stringify(tasks) + "\nRAW_JSON_END" },
56	    ],
57	  };
58	});
59	
60	server.registerTool("update_task_description", {
61	  description: "Update the description of a ClickUp task by its custom ID. Sets the full markdown description.",
62	  inputSchema: {
63	    custom_id: z.string().describe("The custom task ID (e.g. 'MP-42')"),
64	    markdown_description: z.string().describe("The full markdown description to set on the task"),
65	  },
66	}, async ({ custom_id, markdown_description }) => {
67	  await client.updateTaskDescription(custom_id, TEAM_ID, markdown_description);
68	  return { content: [{ type: "text", text: `Description updated on ${custom_id}.` }] };
69	});
70	
71	server.registerTool("add_task_comment", {
72	  description: "Add a comment with markdown content to a ClickUp task. Supports inline images: use ![alt](/local/path.png) for local files (auto-uploaded) or ![alt](https://url) with inline_attachments for already-uploaded files.",
73	  inputSchema: {
74	    custom_id: z.string().describe("The custom task ID (e.g. 'MP-42')"),
75	    comment_text: z.string().describe("The comment body (markdown). Use ![alt](/path/to/file.png) to embed local images inline — they are uploaded automatically."),
76	  },
77	}, async ({ custom_id, comment_text }) => {
78	  // Auto-upload any local file paths referenced as ![alt](/path/to/file)
79	  const localImageRe = /!\[([^\]]*)\]\(([^)]+)\)/g;
80	  const attachments: import("./markdown.js").ClickUpAttachment[] = [];
81	  let resolvedText = comment_text;
82	
83	  const localPaths: Array<{ match: string; alt: string; path: string }> = [];
84	  for (const m of comment_text.matchAll(localImageRe)) {
85	    const ref = m[2];
86	    if (ref.startsWith("/") || ref.startsWith("./") || ref.startsWith("~/")) {
87	      localPaths.push({ match: m[0], alt: m[1], path: ref });
88	    }
89	  }
90	
91	  for (const { match, alt, path } of localPaths) {
92	    const attachment = await client.uploadAttachment(custom_id, TEAM_ID, path);
93	    attachments.push(attachment);
94	    resolvedText = resolvedText.replace(match, `![${alt}](${attachment.url})`);
95	  }
96	
97	  await client.addTaskComment(custom_id, TEAM_ID, resolvedText, attachments);
98	  return { content: [{ type: "text", text: `Comment added to ${custom_id}.` }] };
99	});
100	
