  const tags = getAllTags();
  const tagKeys = Object.keys(tags);
  if (tagKeys.length === 0) return [{ tag: '_' }];
  // Keys are display-cased; normalize to lowercase for URL slugs and deduplicate.
  const seen = new Set<string>();
  return tagKeys
