 1→# CrowdStrike Falcon sensor configuration for NixOS
 2→#
 3→# Prerequisites (manual steps):
 4→# 1. Obtain the Falcon sensor .deb from IT
 5→# 2. Place it at: /etc/nixos/falcon-sensor.deb
 6→#    sudo cp ~/Downloads/falcon-sensor*.deb /etc/nixos/falcon-sensor.deb
 7→# 3. Create /etc/falcon-sensor.env with: FALCON_CID=<your-cid>
 8→#
 9→# This module is only imported if /etc/nixos/falcon-sensor.deb exists.
10→#
11→# Based on: https://github.com/taylanpince/nixos-config
12→{ pkgs, lib, ... }:
13→let
14→  falcon = pkgs.callPackage ./falcon { };
15→
16→  initScript = pkgs.writeScript "init-falcon" ''
17→    #!${pkgs.bash}/bin/sh
18→    set -euo pipefail
19→
20→    # Remove immutable attributes set by CrowdStrike (security feature)
21→    if [ -d /opt/CrowdStrike ]; then
22→      ${pkgs.e2fsprogs}/bin/chattr -i -R /opt/CrowdStrike 2>/dev/null || true
23→    fi
24→
25→    install -d -m 0770 /opt/CrowdStrike
26→
27→    # Update binaries from the nix store, but preserve runtime state files.
28→    # falconstore contains the Agent ID (AID) — if lost, the sensor re-registers
29→    # as a new host and consumes another license seat.
30→    ${pkgs.rsync}/bin/rsync -a --delete \
31→      --exclude=falconstore \
32→      --exclude=falconstore.bak \
33→      --exclude=CsConfig \
34→      "${falcon}/opt/CrowdStrike/" /opt/CrowdStrike/
35→
36→    chown -R root:root /opt/CrowdStrike
37→
38→    # load CID from /etc/falcon-sensor.env (root-only)
39→    . /etc/falcon-sensor.env
40→
41→    # set CID via falconctl inside FHS env
42→    ${falcon}/bin/fs-bash -c "/opt/CrowdStrike/falconctl -s -f --cid=\"$FALCON_CID\""
43→
44→    # sanity print
45→    ${falcon}/bin/fs-bash -c "/opt/CrowdStrike/falconctl -g --cid"
46→  '';
47→in
48→{
49→  systemd.tmpfiles.rules = [
50→    "d /opt/CrowdStrike 0770 root root -"
51→  ];
52→
53→  systemd.services.falcon-sensor = {
54→    description = "CrowdStrike Falcon Sensor";
55→    wantedBy = [ "multi-user.target" ];
56→
57→    unitConfig.DefaultDependencies = false;
58→    after = [ "local-fs.target" ];
59→    conflicts = [ "shutdown.target" ];
60→    before = [
61→      "sysinit.target"
62→      "shutdown.target"
63→    ];
64→
65→    serviceConfig = {
66→      Type = "forking";
67→      PIDFile = "/run/falcond.pid";
68→      ExecStartPre = initScript;
69→      ExecStart = "${falcon}/bin/fs-bash -c \"/opt/CrowdStrike/falcond\"";
70→
71→      Restart = "on-failure";
72→      RestartSec = "15s";
73→
74→      # Avoid systemd giving up during flapping
75→      StartLimitIntervalSec = 0;
76→
77→      TimeoutStopSec = "60s";
78→      KillMode = "process";
79→      Delegate = true;
80→    };
81→  };
82→}
83→

