    30→func WithBaseURL(url string) Option {
    31→	return func(cl *Client) { cl.baseURL = url }
    32→}
    33→
    34→// NewClient creates a new Todoist API client.
    35→func NewClient(token string, opts ...Option) *Client {
    36→	c := &Client{
    37→		token:      token,
    38→		baseURL:    defaultBaseURL,
    39→		httpClient: &http.Client{Timeout: 10 * time.Second},
    40→	}
    41→	for _, o := range opts {
    42→		o(c)
    43→	}
    44→	return c
    45→}
    46→
    47→// do executes an HTTP request against the Todoist API and returns the
    48→// response body bytes. For responses with no content (204) it returns nil.
    49→func (c *Client) do(method, endpoint string, body interface{}) ([]byte, error) {
    50→	var reqBody io.Reader
    51→	if body != nil {
    52→		data, err := json.Marshal(body)
    53→		if err != nil {
    54→			return nil, fmt.Errorf("failed to marshal request body: %w", err)
    55→		}
    56→		reqBody = strings.NewReader(string(data))
    57→	}
    58→
    59→	req, err := http.NewRequest(method, c.baseURL+endpoint, reqBody)
    60→	if err != nil {
    61→		return nil, fmt.Errorf("failed to create request: %w", err)
    62→	}
    63→
    64→	req.Header.Set("Authorization", "Bearer "+c.token)
    65→	req.Header.Set("Content-Type", "application/json")
    66→
    67→	resp, err := c.httpClient.Do(req)
    68→	if err != nil {
    69→		return nil, fmt.Errorf("failed to make request: %w", err)
    70→	}
    71→	defer func() { _ = resp.Body.Close() }()
    72→
    73→	respBody, err := io.ReadAll(resp.Body)
    74→	if err != nil {
    75→		return nil, fmt.Errorf("failed to read response: %w", err)
    76→	}
