   782→// promptTelemetryConsent asks the user if they want to enable telemetry.
   783→// It modifies settings.Telemetry based on the user's choice or flags.
   784→// The caller is responsible for saving settings.
   785→func promptTelemetryConsent(settings *EntireSettings, telemetryFlag bool) error {
   786→	// Handle --telemetry=false flag first (always overrides existing setting)
   787→	if !telemetryFlag {
   788→		f := false
