   797→
   798→	// Skip if env var disables telemetry (record as disabled)
   799→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   800→		f := false
   801→		settings.Telemetry = &f
   802→		return nil
   803→	}
   804→
   805→	consent := true // Default to Yes
   806→	form := NewAccessibleForm(
