    87→// runExplain routes to the appropriate explain function based on flags.
    88→func runExplain(w io.Writer, sessionID, commitRef string, noPager bool) error {
    89→	// Error if both flags are provided
    90→	if sessionID != "" && commitRef != "" {
    91→		return errors.New("cannot specify both --session and --commit")
    92→	}
    93→
    94→	// Route to appropriate handler
    95→	if sessionID != "" {
    96→		return runExplainSession(w, sessionID, noPager)
    97→	}
    98→	if commitRef != "" {
    99→		return runExplainCommit(w, commitRef)
   100→	}
   101→
   102→	// Default: explain current session
   103→	return runExplainDefault(w, noPager)
   104→}
