func TestRunExplainDefault_ShowsBranchInfo(t *testing.T) {
    tmpDir := t.TempDir()
    t.Chdir(tmpDir)

    // Init repo
    repo, err := git.PlainInit(tmpDir, false)
    if err != nil {
        t.Fatalf("failed to init git repo: %v", err)
    }

    // Create initial commit so we have a branch
